# Car is away 13:08 → 18:59 (trip "Babcia"): those hours aren't chargeable,
# the departure/return hours only partly.
now = P(d["generated_at"])
first = slots[0].start
frac = max(0.0, 1.0 - (now - first).total_seconds() / 3600.0)
trip = next(t for t in d["status"]["ev"]["trips"] if t["label"] == "Babcia")
dep, ret = P(trip["depart"]), P(trip["return_end"])
fractions = {first: frac}
for s in slots:
    h0, h1 = s.start, s.start + timedelta(hours=1)
    if h0 >= ret or h1 <= dep:
        continue
    usable = max(0.0, (dep - h0).total_seconds()) + max(0.0, (h1 - ret).total_seconds())
    f = min(1.0, usable / 3600.0)
    if f <= 0.01:
        available.discard(h0)
    else:
        fractions[h0] = f

